import { useEffect, useState } from 'react'
import { useHistory, useParams } from 'react-router'
import { Container } from '../../../../../components'
import ShowSnackbar from '../../../../../components/ShowNotification'
import {
  dateAdd,
  formatDate,
  isDateBefore,
} from '../../../../../helpers/formatDate'
import PropertyPolicySummary from '../../../../CommonContainer/PropertySummaryPage'
import { PolicyContextProvider } from '../../../Policy/context'
import { PROPERTY_LANG } from '../../lang'
import useDraftApi from '../hooks/useDraftApi'

function PropertyAgentSummary() {
  const history = useHistory()
  const { draftId } = useParams()

  const [draftResponseData, setDraftResponseData] = useState({})
  const [draftPolicyDetails, setDraftPolicyDetails] = useState({})

  const [isConvertToPaylater, setIsConvertToPaylater] = useState(false)

  const {
    isGetDraftLoader,
    isSaveLoader,
    isCompleteDraftLoader,
    handleSaveToDraft,
    handleCompleteDraft,
  } = useDraftApi({
    draftId: draftId,
    onGetDraftDetailSuccess: (data) => {
      setDraftResponseData(data)
      setDraftPolicyDetails(data.policy_details)
    },
    onSaveSuccess: () => handleCompleteDraft(),
    onCompleteDraftSuccess: ({ policyId }) => {
      if (isConvertToPaylater) {
        history.push(`/transaction/type/${policyId}`)
        return
      }
      history.push({
        pathname: `/payment/property-protection/${policyId}`,
        state: { policyId },
      })
    },
  })

  useEffect(() => {
    // Auto update start_date & end_date
    if (!draftPolicyDetails || !draftPolicyDetails?.start_date) return
    const minStartDate = formatDate(dateAdd(new Date(), 1, 'day'), 'YYYY-MM-DD')
    if (isDateBefore(draftPolicyDetails?.start_date, minStartDate)) {
      // If date is before today + 1, auto update start date to be today + 1
      const newDraftData = {
        ...draftPolicyDetails,
        start_date: formatDate(minStartDate, 'YYYY-MM-DD'),
        end_date: formatDate(dateAdd(minStartDate, 1, 'year'), 'YYYY-MM-DD'),
      }
      setDraftPolicyDetails(newDraftData)
      handleSaveToDraft(
        newDraftData,
        'mv_quote_summary',
        'mv_quote_summary',
        false
      )
      ShowSnackbar.success({ text: PROPERTY_LANG.startDateAutoUpdateSuccess })
    }
  }, [handleSaveToDraft, draftPolicyDetails])

  const handleSubmit = () => {
    handleSaveToDraft(
      draftPolicyDetails,
      'mv_quote_summary',
      'mv_quote_summary'
    )
  }

  return (
    <Container
      title={PROPERTY_LANG.propertyInsurance}
      loader={isGetDraftLoader || isSaveLoader || isCompleteDraftLoader}
      hideBottomTabs
      showCloseIcon
      onClose={() => history.push('/dashboard')}
      onBackClick={() =>
        history.push(`/property/property-protection/5/form/${draftId}`)
      }
    >
      <PropertyPolicySummary
        step="6"
        totalSteps="6"
        draftResponseData={draftResponseData}
        policyDetail={draftPolicyDetails}
        isConvertToPaylater={isConvertToPaylater}
        setIsConvertToPaylater={setIsConvertToPaylater}
        onSubmit={handleSubmit}
      />
    </Container>
  )
}

function WrappedPropertyAgentSummary(props) {
  return (
    <PolicyContextProvider>
      <PropertyAgentSummary {...props} />
    </PolicyContextProvider>
  )
}

export default WrappedPropertyAgentSummary
